hooks.command:
node -e "
const input = JSON.parse(process.env.CLAUDE_TOOL_INPUT || '{}');
const path = input.file_path || '';
if (path.includes('apps/frontend/') && !path.includes('agent.md')) {
  process.stdout.write('[Agent] Tâche frontend détectée → utiliser l\'agent frontend-dev\n');
} else if (path.includes('apps/backend/') && !path.includes('agent.md')) {
  process.stdout.write('[Agent] Tâche backend détectée → utiliser l\'agent backend-dev\n');
}
"

node -e "
const input = JSON.parse(process.env.CLAUDE_TOOL_INPUT || '{}');
const cmd = input.command || '';
if (cmd.includes('git commit') || cmd.includes('git push') || cmd.includes('gh pr')) {
  process.stdout.write('[Agent] Avant de committer/PR → lancer code-reviewer d\'abord\n');
}
"
